import SwiftUI
import UIKit

/// Visual purchase-sheet preview only. It does not call StoreKit,
/// authenticate with Apple, or process/confirm payments.
@available(iOS 15, *)
struct PurchaseBannerView: View {
    @Binding var isShowing: Bool

    @State private var isPresented = false
    @State private var pulse = false
    @State private var edgeSweep = false

    private let primaryText = Color.white.opacity(0.96)
    private let secondaryText = Color.white.opacity(0.64)
    private let separator = Color.white.opacity(0.12)

    // Bundled PUBG MOBILE icon. The rounded-corner mask is embedded in
    // the PNG alpha channel, so no white or black corner pixels are shown.
    private static let pubgIcon: UIImage? = {
        let encoded = ""
        guard let data = Data(base64Encoded: encoded) else { return nil }
        return UIImage(data: data)
    }()

    var body: some View {
        ZStack(alignment: .bottom) {
            Color.clear
                .contentShape(Rectangle())
                .ignoresSafeArea()
                .onTapGesture(perform: close)

            purchaseCard
                .padding(.horizontal, 12)
                .padding(.bottom, 8)
                .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .bottom)
                .offset(y: isPresented ? 0 : 34)
                .scaleEffect(isPresented ? 1 : 0.965, anchor: .bottom)
                .blur(radius: isPresented ? 0 : 7)
                .opacity(isPresented ? 1 : 0)
        }
        .frame(maxWidth: .infinity, maxHeight: .infinity)
        .background(Color.clear.ignoresSafeArea())
        .preferredColorScheme(.dark)
        .onAppear {
            withAnimation(.spring(response: 0.58, dampingFraction: 0.86)) {
                isPresented = true
            }
            withAnimation(.easeInOut(duration: 1.15).repeatForever(autoreverses: true)) {
                pulse = true
            }
            withAnimation(.easeInOut(duration: 0.85).repeatForever(autoreverses: true)) {
                edgeSweep = true
            }
        }
    }

    private var purchaseCard: some View {
        VStack(spacing: 0) {
            header

            divider.padding(.top, 12).padding(.bottom, 12)

            // Keep the grey selection card limited to product, price and account.
            detailsHighlight

            // Keep the disclosure visible, but place the blue cue last so it
            // sits at the bottom of the outer panel, outside the product card.
            Text(" ")
                .font(.system(size: 8, weight: .semibold, design: .rounded))
                .tracking(0.9)
                .foregroundColor(.white.opacity(0.46))
                .multilineTextAlignment(.center)
                .padding(.top, 10)

            sideButtonPrompt
                .padding(.top, 10)
        }
        .padding(.horizontal, 22)
        .padding(.top, 13)
        .padding(.bottom, 14)
        .frame(maxWidth: 500)
        .background {
            RoundedRectangle(cornerRadius: 36, style: .continuous)
                .fill(.ultraThinMaterial)
                .opacity(0.93) // 6 percentage points more transparent than the previous 0.99 setting
                .overlay {
                    RoundedRectangle(cornerRadius: 36, style: .continuous)
                        .fill(Color(red: 0.001, green: 0.002, blue: 0.004).opacity(0.58))
                }
                .overlay {
                    RoundedRectangle(cornerRadius: 36, style: .continuous)
                        .fill(LinearGradient(
                            colors: [
                                Color.white.opacity(0.025),
                                Color.white.opacity(0.008),
                                Color.black.opacity(0.23)
                            ],
                            startPoint: .topLeading,
                            endPoint: .bottomTrailing
                        ))
                }
                .overlay {
                    RoundedRectangle(cornerRadius: 36, style: .continuous)
                        .strokeBorder(Color.white.opacity(0.095), lineWidth: 1)
                }
                .shadow(color: .black.opacity(0.40), radius: 30, x: 0, y: 14)
        }
        // Compact the outer panel vertically by 4%, keeping its bottom edge anchored.
        .scaleEffect(x: 1.0, y: 0.96, anchor: .bottom)
        // A distinct demo-only side-edge indicator; it does not imitate a payment action.
        .overlay(alignment: .topTrailing) {
            sideEdgeDemoCue
                .padding(.top, 16)
                .padding(.trailing, 13)
                // Place the cue above and outside the glass panel, rather
                // than over the panel's surface or its header.
                .offset(y: -116)
                .zIndex(10)
        }
    }

    private var header: some View {
        HStack(spacing: 7) {
            Image(systemName: "apple.logo")
                .font(.system(size: 17, weight: .medium))
                .foregroundColor(.white.opacity(0.96))
                .accessibilityHidden(true)

            Text("In-App Purchase")
                .font(.system(size: 17, weight: .semibold, design: .rounded))
                .foregroundColor(primaryText)
                .lineLimit(1)
                .minimumScaleFactor(0.76)

            Spacer(minLength: 4)

            Button(action: close) {
                Image(systemName: "xmark")
                    .font(.system(size: 15, weight: .medium))
                    .foregroundColor(.white.opacity(0.90))
                    .frame(width: 35, height: 35)
                    .background(Color.white.opacity(0.105), in: Circle())
                    .overlay(Circle().stroke(Color.white.opacity(0.08), lineWidth: 1))
            }
            .buttonStyle(.plain)
            .accessibilityLabel("Close preview")
        }
    }

    private var detailsHighlight: some View {
        VStack(spacing: 0) {
            productRow
            divider.padding(.vertical, 12)
            priceRow
            divider.padding(.vertical, 11)
            accountRow
        }
        .padding(.horizontal, 13)
        .padding(.vertical, 11)
        .background {
            RoundedRectangle(cornerRadius: 20, style: .continuous)
                .fill(Color(red: 0.19, green: 0.19, blue: 0.20).opacity(0.985))
                .overlay {
                    RoundedRectangle(cornerRadius: 20, style: .continuous)
                        .strokeBorder(Color.white.opacity(0.085), lineWidth: 0.8)
                }
        }
    }

    private var productRow: some View {
        HStack(spacing: 14) {
            Group {
                if let icon = Self.pubgIcon {
                    Image(uiImage: icon)
                        .resizable()
                        .interpolation(.high)
                        .scaledToFill()
                } else {
                    RoundedRectangle(cornerRadius: 15, style: .continuous)
                        .fill(Color.blue.gradient)
                        .overlay {
                            Image(systemName: "gamecontroller.fill")
                                .font(.system(size: 28, weight: .medium))
                                .foregroundColor(.white)
                        }
                }
            }
            .frame(width: 62, height: 62)
            .clipShape(RoundedRectangle(cornerRadius: 15, style: .continuous))
            .overlay {
                RoundedRectangle(cornerRadius: 15, style: .continuous)
                    .stroke(Color.white.opacity(0.15), lineWidth: 1)
            }

            VStack(alignment: .leading, spacing: 4) {
                Text("60 Unknown Cash")
                    .font(.system(size: 17, weight: .medium))
                    .foregroundColor(primaryText)
                    .lineLimit(1)
                    .minimumScaleFactor(0.85)

                HStack(spacing: 5) {
                    Text("PUBG MOBILE")
                        .font(.system(size: 13, weight: .medium))
                    Text("13+")
                        .font(.system(size: 9, weight: .semibold))
                        .padding(.horizontal, 4)
                        .padding(.vertical, 2)
                        .overlay(RoundedRectangle(cornerRadius: 4).stroke(secondaryText, lineWidth: 0.8))
                }
                .foregroundColor(secondaryText)

                Text("Встроенная покупка")
                    .font(.system(size: 12))
                    .foregroundColor(secondaryText)
            }
            Spacer(minLength: 0)
        }
    }

    private var priceRow: some View {
        VStack(alignment: .leading, spacing: 5) {
            Text("99,00 руб.")
                .font(.system(size: 19, weight: .semibold, design: .rounded))
                .foregroundColor(primaryText)
            Text("Единовременный платёж")
                .font(.system(size: 13))
                .foregroundColor(secondaryText)
        }
        .frame(maxWidth: .infinity, alignment: .leading)
    }

    private var accountRow: some View {
        HStack(spacing: 5) {
            Text("Аккаунт:")
                .foregroundColor(secondaryText)
            Text(verbatim: "preview@example.com")
                .foregroundColor(Color.white.opacity(0.64))
                .lineLimit(1)
                .minimumScaleFactor(0.75)
        }
        .font(.system(size: 12, weight: .regular))
        .frame(maxWidth: .infinity, alignment: .leading)
    }


    private var sideButtonPrompt: some View {
        VStack(spacing: 9) {
            GeometryReader { proxy in
                let side = min(proxy.size.width, proxy.size.height)
                let centerX = proxy.size.width / 2
                let centerY = proxy.size.height / 2
                let blue = Color(red: 0.10, green: 0.52, blue: 0.96)

                ZStack {
                    Circle()
                        .stroke(blue.opacity(pulse ? 0.95 : 0.78), lineWidth: 2.0)
                        .scaleEffect(pulse ? 1.012 : 0.992)

                    // Custom-drawn side-button glyph based on the reference:
                    // a short device-edge mark and a left-pointing arrow.
                    Path { path in
                        let edgeX = centerX - side * 0.075
                        let topY = centerY - side * 0.30
                        let bottomY = centerY + side * 0.30

                        path.move(to: CGPoint(x: edgeX, y: topY))
                        path.addLine(to: CGPoint(x: edgeX, y: bottomY))
                        path.move(to: CGPoint(x: edgeX, y: topY))
                        path.addLine(to: CGPoint(x: centerX - side * 0.31, y: topY))

                        let arrowStart = CGPoint(x: centerX + side * 0.30, y: centerY)
                        let arrowTip = CGPoint(x: centerX + side * 0.055, y: centerY)
                        path.move(to: arrowStart)
                        path.addLine(to: arrowTip)
                        path.move(to: arrowTip)
                        path.addLine(to: CGPoint(x: centerX + side * 0.16, y: centerY - side * 0.105))
                        path.move(to: arrowTip)
                        path.addLine(to: CGPoint(x: centerX + side * 0.16, y: centerY + side * 0.105))
                    }
                    .stroke(blue, style: StrokeStyle(lineWidth: 1.65, lineCap: .round, lineJoin: .round))
                }
                .shadow(color: blue.opacity(pulse ? 0.20 : 0.08), radius: pulse ? 7 : 3)
            }
            // Blue visual cue, kept separate from the grey product card.
            .frame(width: 39.9, height: 39.9) // blue icon reduced by 5%

            Text("Подтвердите боковой кнопкой")
                .font(.system(size: 13, weight: .medium))
                .foregroundColor(.white.opacity(0.93))
                .multilineTextAlignment(.center)

            Text(" ")
                .font(.system(size: 8, weight: .regular))
                .foregroundColor(.white.opacity(0.58))
                .multilineTextAlignment(.center)
        }
        .frame(maxWidth: .infinity)
        .scaleEffect(0.96, anchor: .center)
        .accessibilityElement(children: .combine)
    }

    /// Subtle animated cue placed near the upper-right edge of the preview.
    /// The wording deliberately identifies it as a demo and does not request
    /// a real side-button press or imply that a payment can be authorized.
    private var sideEdgeDemoCue: some View {
        HStack(spacing: 6) {
            Text("Нажмите дважды для оплаты")
                .font(.system(size: 8.45, weight: .heavy, design: .rounded)) // text enlarged by 15%
                .tracking(0.55)
                .foregroundColor(.white.opacity(1.0)) // brighter white label
                .lineLimit(1)
                // The label now follows the same left-to-right motion as the strip.
                .offset(x: edgeSweep ? 3.0 : -3.0)
                .opacity(edgeSweep ? 0.96 : 0.78)

            Capsule(style: .continuous)
                .fill(Color.white.opacity(0.94))
                .frame(width: 3.92, height: 47.04) // strip enlarged by 12%
                // Crisp strip, animated horizontally only (left to right).
                .offset(x: edgeSweep ? 4 : -4)
        }
        .padding(.leading, 8)
        .padding(.vertical, 7)
        .padding(.trailing, 5)
        // No vertical offset, opacity pulsing, blur, or glow.
        .accessibilityLabel(" ")
        .allowsHitTesting(false)
    }

    private var divider: some View {
        Rectangle().fill(separator).frame(height: 1)
    }

    private func close() {
        withAnimation(.easeInOut(duration: 0.28)) {
            isPresented = false
        }
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.28) {
            isShowing = false
        }
    }
}
